func:
// Получаем текст сообщения от пользователя
const text = msg.payload.content;
const chatId = msg.payload.chatId;

// Проверяем, что есть текст
if (!text) {
    return null;
}

// Отвечаем на команду /start
if (text === "/start") {
    msg.payload = {
        chatId: chatId,
        type: "message",
        content: "Привет! Я бот лабораторной №2. Напиши /echo <текст> — и я повторю за тобой. Или просто напиши что-нибудь — я отвечу эхом."
    };
    return msg;
}

// Отвечаем на команду /echo
if (text.startsWith("/echo ")) {
    const echoText = text.substring(6);
    msg.payload = {
        chatId: chatId,
        type: "message",
        content: "Эхо: " + echoText
    };
    return msg;
}

// На любое другое сообщение — эхо-ответ
msg.payload = {
    chatId: chatId,
    type: "message",
    content: "Ты написал(а): " + text
};
return msg;
